// Which companies to compute performance for. The sheet export is the only input; there is no period.
const BUS = ['bu1', 'bu2'];
const input = $input.first().json;
const source = Object.assign({}, input, input.body || {});
const requested = String(source.bu || 'all').toLowerCase();
if (requested !== 'all' && !BUS.includes(requested)) throw new Error(`bu harus salah satu dari: all, ${BUS.join(', ')}`);
const bus = requested === 'all' ? BUS : [requested];
return [{ json: { trigger: 'manual', plans: bus.map((bu) => ({ bu, period: '' })) } }];

// Turns the Tracker rows into one CSV per planned report. Only the columns the generator needs are kept, so PIC
// names, phone numbers, emails and CRM links never leave n8n. Dates arrive as Google Sheets serial numbers and are
// written as ISO dates, which removes any M/D versus D/M ambiguity.
const COLUMNS = ["Company", "Channel", "Source", "Campaign", "Campaign Hardware", "Industry", "Remark", "Inbound Date", "MQL Date", "Proposal Price Quote Date", "ARR + OTF (Tanpa PPN)", "Deal Won Date", "Total Contract Deal Won", "BU", "Record Key", "SQL Date", "Total Contract SQL"];
const DATE_COLUMNS = new Set(["Inbound Date", "MQL Date", "Proposal Price Quote Date", "Deal Won Date", "SQL Date"]);
const MONEY_COLUMNS = new Set(["ARR + OTF (Tanpa PPN)", "Total Contract Deal Won", "Total Contract SQL"]);
const SERIAL_EPOCH = Date.UTC(1899, 11, 30);
const normalize = (name) => String(name).replace(/\s+/g, ' ').trim();

function cell(column, value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'number') {
    if (DATE_COLUMNS.has(column)) {
      // Serial 30000 is 1982 and 80000 is 2118. Anything else (for example 20260119 typed as a number) is left as
      // text so the generator reports it instead of turning it into a nonsense date.
      if (value < 30000 || value > 80000) return String(value);
      return new Date(SERIAL_EPOCH + Math.floor(value) * 86400000).toISOString().slice(0, 10);
    }
    if (MONEY_COLUMNS.has(column)) return String(Math.round(value * 100) / 100);
    return String(value);
  }
  return String(value).trim();
}

const quote = (text) => (/[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text);

// The Sheets API leaves out empty cells, so a column is judged missing only when NO row has it.
const squash = (name) => name.toLowerCase().replace(/[^a-z0-9]/g, '');
const seen = new Set();
const rows = [];
for (const item of $input.all()) {
  const byName = {};
  for (const [key, value] of Object.entries(item.json)) {
    const name = normalize(key);
    byName[name] = value;
    seen.add(name);
  }
  const values = COLUMNS.map((column) => cell(column, byName[column]));
  if (values.some((v) => v !== '')) rows.push(values.map(quote).join(','));
}
if (!rows.length) throw new Error('Sheet tidak mengembalikan baris data');

const missing = COLUMNS.filter((column) => !seen.has(column));
if (missing.length) {
  const hints = missing.map((column) => {
    const close = [...seen].filter((name) => squash(name) === squash(column));
    return close.length ? `${column} (header mirip: "${close[0]}")` : column;
  });
  throw new Error(`Kolom tidak ditemukan di satu baris pun (tidak ada di sheet atau kosong seluruhnya): ${hints.join('; ')}. Baris dibaca: ${rows.length}, header unik: ${seen.size}`);
}

const csv = [COLUMNS.map(quote).join(','), ...rows].join('\n') + '\n';
const plans = $('Normalize Plan').first().json.plans;
return plans.map((plan) => ({ json: { bu: plan.bu, period: plan.period, csv, rows: rows.length } }));

// Maps each service response onto the parameters of sql/insert_performance.sql. Only aggregates travel from here on.
return $input.all().map((item) => {
  const r = item.json;
  return { json: { params: [r.bu, r.as_of, r.source_sha256, r.generator_version, JSON.stringify(r.data)], bu: r.bu, as_of: r.as_of, days: r.days, rows_in_bu: r.rows_in_bu } };
});

// One entry per company: whether a new snapshot was stored or the same export had already been stored today.
const prepared = $('Prepare Insert').all();
return [{ json: { snapshots: $input.all().map((item, i) => ({ bu: prepared[i].json.bu, as_of: prepared[i].json.as_of, days: prepared[i].json.days, snapshot_id: item.json.snapshot_id, inserted: item.json.inserted })) } }];

// Runs once per failed item. Short, aggregate-only text: it reads only named fields of the error and caps the length, so no
// request body (the CSV) can leak into it.
let plan;
try { plan = $('Build CSV').item.json; } catch (e) { plan = $('Build CSV').first().json; }
const err = $json.error !== undefined ? $json.error : $json;
const parts = [];
const add = (value) => {
  if (value === undefined || value === null || value === '') return;
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  if (!parts.includes(text)) parts.push(text);
};
if (typeof err === 'string') {
  add(err);
} else {
  add(err.httpCode);
  add(err.message);
  add(err.description);
  add(err.cause && err.cause.message);
  add(err.context && err.context.data);
}
const detail = (parts.join(' | ') || 'penyebab tidak diketahui').replace(/\s+/g, ' ').slice(0, 1200);
return { json: { text: `Performa ${String(plan.bu).toUpperCase()} GAGAL dihitung: ${detail}` } };
